'use strict';

/**
 * Invoice PDF Template
 *
 * Generates a professional A4 PDF invoice using PDFKit.
 * The PDF stream is piped to a buffer and returned for Cloudinary upload.
 *
 * Layout:
 *   Header:     TenantFlow branding + invoice number, issue date, due date
 *   Bill To:    Tenant name, billing address, tax ID (GSTIN)
 *   Line Items: Description | Qty | Unit Price | Amount (table)
 *   Totals:     Subtotal, Tax (18% GST), Total, Amount Paid, Amount Due
 *   Footer:     "Thank you for your business. Invoice generated by TenantFlow."
 *
 * REF: docs/IMPLEMENTATION_ROADMAP.md §7.1 T4.6
 */

const PDFDocument = require('pdfkit');

// ── Color Palette ──────────────────────────────────────────────
const COLORS = {
  primary:     '#4F46E5',  // Indigo brand color
  headerBg:    '#1E1B4B',  // Dark header background
  headerText:  '#FFFFFF',
  tableHeader: '#F1F5F9',
  tableRow:    '#FFFFFF',
  tableRowAlt: '#F8FAFC',
  border:      '#E2E8F0',
  text:        '#1E293B',
  muted:       '#64748B',
  accent:      '#EF4444',  // Red for Amount Due when > 0
  success:     '#10B981',  // Green for paid
};

const FONT_REGULAR = 'Helvetica';
const FONT_BOLD    = 'Helvetica-Bold';

/**
 * Convert paise to formatted rupee string.
 * e.g. 99900 → "₹999.00"
 */
const formatCurrency = (paise) => {
  const rupees = paise / 100;
  return `₹${rupees.toFixed(2)}`;
};

/**
 * Format a date for display.
 * e.g. 2024-01-15 → "15 Jan 2024"
 */
const formatDate = (date) => {
  if (!date) return '—';
  return new Date(date).toLocaleDateString('en-IN', {
    day:   '2-digit',
    month: 'short',
    year:  'numeric',
  });
};

/**
 * Generate an invoice PDF as a Buffer.
 *
 * @param {Object} invoice   - Invoice document (with lineItems, totals)
 * @param {Object} tenant    - Tenant document (name, billingAddress, taxId)
 * @param {Object} subscription - Subscription document
 * @returns {Promise<Buffer>} PDF buffer ready for Cloudinary upload
 */
const generateInvoicePdf = (invoice, tenant, subscription) => {
  return new Promise((resolve, reject) => {
    const doc    = new PDFDocument({ size: 'A4', margin: 50 });
    const chunks = [];

    doc.on('data', (chunk) => chunks.push(chunk));
    doc.on('end',  ()      => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);

    const pageW  = doc.page.width;   // 595
    const margin = 50;
    const contentW = pageW - 2 * margin;

    // ── Header Block ─────────────────────────────────────────
    doc.rect(0, 0, pageW, 120).fill(COLORS.headerBg);

    // Brand name
    doc.fillColor(COLORS.headerText)
       .font(FONT_BOLD)
       .fontSize(24)
       .text('TenantFlow', margin, 30);

    // Tagline
    doc.font(FONT_REGULAR)
       .fontSize(10)
       .fillColor('#A5B4FC')
       .text('SaaS Billing Platform', margin, 58);

    // INVOICE label
    doc.font(FONT_BOLD)
       .fontSize(28)
       .fillColor(COLORS.headerText)
       .text('INVOICE', pageW - margin - 160, 25, { align: 'right', width: 160 });

    // Invoice number
    doc.font(FONT_REGULAR)
       .fontSize(10)
       .fillColor('#C7D2FE')
       .text(invoice.invoiceNumber, pageW - margin - 160, 58, { align: 'right', width: 160 });

    doc.moveDown();

    // ── Invoice Meta (Issue Date / Due Date) ─────────────────
    let y = 140;
    doc.fillColor(COLORS.muted).font(FONT_REGULAR).fontSize(9);
    doc.text('ISSUE DATE',    margin, y);
    doc.text('DUE DATE',      margin + 150, y);
    doc.text('STATUS',        margin + 300, y);

    y += 14;
    doc.fillColor(COLORS.text).font(FONT_BOLD).fontSize(10);
    doc.text(formatDate(invoice.createdAt), margin, y);
    doc.text(formatDate(invoice.dueDate),   margin + 150, y);

    const statusColor = invoice.status === 'paid' ? COLORS.success : (invoice.amountDue > 0 ? COLORS.accent : COLORS.muted);
    doc.fillColor(statusColor).text(invoice.status.toUpperCase(), margin + 300, y);

    // ── Bill To ───────────────────────────────────────────────
    y += 36;
    doc.fillColor(COLORS.muted).font(FONT_REGULAR).fontSize(9).text('BILL TO', margin, y);

    y += 14;
    doc.fillColor(COLORS.text).font(FONT_BOLD).fontSize(11).text(tenant.name || 'Unnamed Tenant', margin, y);

    y += 16;
    doc.font(FONT_REGULAR).fontSize(9).fillColor(COLORS.muted);

    const addr = tenant.billingAddress || {};
    if (addr.line1)      { doc.text(addr.line1, margin, y); y += 12; }
    if (addr.line2)      { doc.text(addr.line2, margin, y); y += 12; }
    if (addr.city || addr.state || addr.postalCode) {
      const cityLine = [addr.city, addr.state, addr.postalCode].filter(Boolean).join(', ');
      doc.text(cityLine, margin, y); y += 12;
    }
    if (addr.country)    { doc.text(addr.country, margin, y); y += 12; }
    if (tenant.taxId)    { doc.text(`GSTIN: ${tenant.taxId}`, margin, y); y += 12; }
    if (tenant.billingEmail) { doc.text(tenant.billingEmail, margin, y); y += 12; }

    // ── Billing Period ────────────────────────────────────────
    y += 8;
    doc.fillColor(COLORS.muted).font(FONT_REGULAR).fontSize(9);
    doc.text('BILLING PERIOD', margin, y);
    y += 14;
    doc.fillColor(COLORS.text).font(FONT_REGULAR).fontSize(9);
    doc.text(`${formatDate(invoice.periodStart)} – ${formatDate(invoice.periodEnd)}`, margin, y);

    // ── Line Items Table ──────────────────────────────────────
    y += 28;
    const colWidths = [contentW * 0.5, contentW * 0.12, contentW * 0.19, contentW * 0.19];
    const colX      = [margin, margin + colWidths[0], margin + colWidths[0] + colWidths[1], margin + colWidths[0] + colWidths[1] + colWidths[2]];

    // Table header background
    doc.rect(margin, y, contentW, 20).fill(COLORS.tableHeader);

    doc.fillColor(COLORS.muted).font(FONT_BOLD).fontSize(8);
    doc.text('DESCRIPTION', colX[0] + 4, y + 6);
    doc.text('QTY',         colX[1], y + 6, { width: colWidths[1], align: 'center' });
    doc.text('UNIT PRICE',  colX[2], y + 6, { width: colWidths[2], align: 'right' });
    doc.text('AMOUNT',      colX[3], y + 6, { width: colWidths[3], align: 'right' });

    y += 20;

    // Table rows
    invoice.lineItems.forEach((item, idx) => {
      const rowH   = 22;
      const bgColor = idx % 2 === 0 ? COLORS.tableRow : COLORS.tableRowAlt;

      doc.rect(margin, y, contentW, rowH).fill(bgColor);

      // Highlight credits in green, charges in normal text
      const amountColor = item.amount < 0 ? COLORS.success : COLORS.text;

      doc.fillColor(COLORS.text).font(FONT_REGULAR).fontSize(8.5);
      doc.text(item.description, colX[0] + 4, y + 7, { width: colWidths[0] - 8, ellipsis: true });

      doc.text(String(item.quantity), colX[1], y + 7, { width: colWidths[1], align: 'center' });

      const unitLabel = item.unitPrice < 0 ? `(${formatCurrency(Math.abs(item.unitPrice))})` : formatCurrency(item.unitPrice);
      doc.text(unitLabel, colX[2], y + 7, { width: colWidths[2], align: 'right' });

      doc.fillColor(amountColor);
      const amountLabel = item.amount < 0 ? `(${formatCurrency(Math.abs(item.amount))})` : formatCurrency(item.amount);
      doc.text(amountLabel, colX[3], y + 7, { width: colWidths[3], align: 'right' });

      y += rowH;
    });

    // Table bottom border
    doc.strokeColor(COLORS.border).lineWidth(0.5).moveTo(margin, y).lineTo(margin + contentW, y).stroke();

    // ── Totals Block ──────────────────────────────────────────
    y += 12;
    const totalsX     = margin + contentW * 0.55;
    const totalsLabelW = contentW * 0.25;
    const totalsValueW = contentW * 0.20;

    const _totalsRow = (label, value, bold = false, color = COLORS.text) => {
      doc.font(bold ? FONT_BOLD : FONT_REGULAR).fontSize(9).fillColor(COLORS.muted);
      doc.text(label, totalsX, y, { width: totalsLabelW });
      doc.font(bold ? FONT_BOLD : FONT_REGULAR).fontSize(9).fillColor(color);
      doc.text(value, totalsX + totalsLabelW, y, { width: totalsValueW, align: 'right' });
      y += 16;
    };

    _totalsRow('Subtotal',          formatCurrency(invoice.subtotal));
    _totalsRow(`Tax (${invoice.taxRate}% GST)`, formatCurrency(invoice.taxAmount));

    // Separator line before Total
    doc.strokeColor(COLORS.border).lineWidth(0.5)
       .moveTo(totalsX, y - 4).lineTo(totalsX + totalsLabelW + totalsValueW, y - 4).stroke();

    _totalsRow('Total',             formatCurrency(invoice.total), true, COLORS.text);
    _totalsRow('Amount Paid',       formatCurrency(invoice.amountPaid), false, COLORS.success);

    // Amount Due — highlighted red if > 0
    const dueColor = invoice.amountDue > 0 ? COLORS.accent : COLORS.success;
    y += 2;
    doc.rect(totalsX - 4, y - 2, totalsLabelW + totalsValueW + 8, 22).fill(invoice.amountDue > 0 ? '#FEF2F2' : '#F0FDF4');
    _totalsRow('Amount Due', formatCurrency(invoice.amountDue), true, dueColor);

    // ── Footer ────────────────────────────────────────────────
    const footerY = doc.page.height - 60;
    doc.strokeColor(COLORS.border).lineWidth(0.5)
       .moveTo(margin, footerY - 10).lineTo(pageW - margin, footerY - 10).stroke();

    doc.font(FONT_REGULAR).fontSize(8.5).fillColor(COLORS.muted)
       .text(
         'Thank you for your business. Invoice generated by TenantFlow.',
         margin, footerY,
         { align: 'center', width: contentW }
       );

    doc.font(FONT_REGULAR).fontSize(7.5).fillColor(COLORS.muted)
       .text(
         `Invoice ${invoice.invoiceNumber} • Generated on ${formatDate(new Date())}`,
         margin, footerY + 14,
         { align: 'center', width: contentW }
       );

    doc.end();
  });
};

module.exports = { generateInvoicePdf };
